insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 11, 'Por que? Porque não vos amo? Deus o sabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 12, 'Mas o que eu faço, ainda o farei, para cortar a oportunidade daqueles que buscam oportunidade para serem considerados como nós naquilo em que se orgulham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 13, 'Porque tais falsos apóstolos são trabalhadores fraudulentos, fingindo serem apóstolos de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 14, 'E isto não é algo maravilhoso; porque o mesmo Satanás se transforma [fingindo ser] anjo de luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 15, 'Portanto não é muita [surpresa] se também seus trabalhadores se transformam, [fingindo serem] trabalhadores da justiça; o fim dos quais será conforme as suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 16, 'Outra vez digo, que ninguém pense que sou tolo; ou se não, recebei a mim como se eu fosse tolo, para que eu também me orgulhe um pouco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 17, 'O que eu estou dizendo, não estou dizendo conforme o Senhor, mas sim como um tolo, nesta firme orgulho confiante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 18, 'Porque muitos se orgulham segundo a carne; e também eu me orgulharei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 19, 'Porque vós, sendo [tão] sábios, tolerais com boa vontade os tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 20, 'Pois vós tolerais se alguém vos põe como escravos, se alguém [vos] explora, se alguém se aproveita [de vós] , se alguém age com arrogância, se alguém vos fere no rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 21, 'Eu digo como algo desonroso, como se tivéssemos estado fracos; mas naquilo em que algum outro é atrevido, eu também sou atrevido (falo como tolo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 22, 'Eles são hebreus? Eu também. Eles são israelitas? Eu também. Eles são semente de Abraão? Eu também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 23, 'Eles são servidores de Cristo? (Falo como tolo:) eu sou mais ainda; em trabalhos, muito mais; em feridas, mais; em prisões, muito mais; em [perigo] de morte, muitas vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 24, 'Eu já recebi dos judeus cinco vezes quarenta [açoites] menos um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 25, 'Por três vezes já fui espancado com varas, uma vez fui apedrejado, três vezes sofri naufrágios, passei uma noite e um dia [à deriva] no mar profundo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 26, 'Muitas vezes em viagens, em perigos de rios, em perigos de assaltantes, em perigos dos da [minha] nação, em perigos dos gentios, em perigos na cidade, em perigos no deserto, em perigos no mar, em perigos entre falsos irmãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 27, 'Em trabalho e fadiga, muitas vezes em vigílias, em fome e em sede, em jejuns muitas vezes, em frio e nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 28, 'Além das coisas de fora, a cada dia me vem preocupações de todas as igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 29, 'Quem enfraquece, que eu também não enfraqueça? Quem sofre um tropeço na fé, que eu não me inflame?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 30, 'Se é necessário se orgulhar, eu me orgulharei das coisas relativas à minha fraqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 31, 'O Deus e Pai de nosso Senhor Jesus Cristo, que é bendito eternamente, sabe que eu não estou mentindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 32, 'Em Damasco, o governador subordinado ao Rei Aretas pôs guardas na cidade dos damascenos, querendo me prender.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 33, 'E me fizeram descer num cesto por uma janela da muralha [da cidade] , e [assim] escapei das mãos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 1, 'Verdadeiramente não me convém me orgulhar; porque eu virei para as visões e revelações do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 2, 'Conheço um homem em Cristo que, catorze anos atrás, foi arrebatado até o terceiro céu (se no corpo, não sei; se fora do corpo, não sei; Deus o sabe).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 3, 'E sei que o tal homem (se no corpo, se fora do corpo, não sei; Deus o sabe),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 4, 'Foi arrebatado ao paraíso, e ouviu palavras inexprimíveis, que ao homem não é lícito falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 5, 'D [este] tal eu me orgulharei, mas de mim mesmo não me orgulharei, a não ser em minhas fraquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 6, 'Porque se eu quiser me orgulhar, não serei tolo; porque direi a verdade; porém eu me contenho, para que ninguém me considere mais do que aquilo que vê em mim, ou ouve de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 7, 'E para que eu não ficasse arrogante pela excelência das revelações, me foi dado um espinho na carne, [que é] um mensageiro de Satanás, para me atormentar, para que eu não ficasse arrogante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 8, 'Três vezes eu orei ao Senhor por causa disso, para que [isso] de afastasse de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 9, 'Mas ele me disse: “Minha graça te basta, porque meu poder se aperfeiçoa na fraqueza”. Por isso, com muito prazer, eu me orgulharei nas minhas fraquezas, para que o poder de Cristo habite em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 10, 'Por isso tenho prazer nas fraquezas, nos insultos, nas necessidades, nas perseguições, nas angústias por causa de Cristo; porque quando estou fraco, então fico forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 11, 'Eu me fiz de tolo ao me orgulhar; [mas] vós me obrigastes [a isso] ; porque eu devia ser louvado por vós, pois eu em coisa nenhuma fui inferior aos “superapóstolos”, ainda que eu nada seja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 12, 'Os sinais do [meu] apostolado foram efetuados entre vós em toda paciência, em sinais, milagres e maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 13, 'Afinal, qual foi a coisa em que fostes inferiores às outras igrejas, a não ser em que eu mesmo não vos fui incômodo? Perdoai-me esta injustiça!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 14, 'Eis que estou prestes a vir pela terceira vez até vós, e não vos serei incômodo como um peso. Porque eu não busco o [que é] vosso, mas sim a vós. Porque os filhos não devem guardar bens para os pais, mas sim os pais para os filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 15, 'E eu de muita boa vontade me gastarei, e me deixarei gastar por vossas almas, ainda que quanto mais eu vos amo, menos sou amado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 16, 'Mas que assim seja, que eu não fui incômodo para convosco. Mas, como eu era astuto, eu vos tomei por engano!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 17, 'Por acaso eu me aproveitei de vós, por meio de alguém que enviei até vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 18, 'Eu roguei a Tito, e enviei ao irmão com ele; por acaso Tito se aproveitou de vós? Por acaso não andamos nós no mesmo espírito, e nos mesmos passos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 19, 'Pensais ainda que nós nos desculpamos convosco? Falamos diante de Deus em Cristo; e [fazemos] tudo isto, ó amados, para vossa edificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 20, 'Porque eu temo que, quando vier, eu não vos encontre da maneira que eu quero; e vós me encontreis da maneira que não quereis; para que não [haja] brigas, invejas, iras, rivalidades, difamações, fofocas, arrogâncias e tumultos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 12, 21, 'Para que, quando eu vier outra vez, meu Deus não me humilhe para convosco, e chore por muitos dos que antes pecaram, [e ainda] se não arrependeram da imundícia, e fornicação, e promiscuidade que cometeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 1, 'Esta é a terceira vez [que] venho até vós; pela boca de duas ou três testemunhas toda palavra será firmada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 2, 'Eu já tinha dito antes, e disse quando estive presente pela segunda vez, e agora ausente o escrevo aos que pecaram anteriormente, e a todos os demais, que se vier outra vez, não [lhes] serei tolerante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 3, 'Pois buscais prova de que Cristo fala em mim, o qual em vós não é fraco, mas que é poderoso entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 4, 'Porque ainda que tenha sido crucificado por fraqueza, contudo ele vive pelo poder de Deus. Porque também nós somos fracos nele, porém com ele viveremos pelo poder de Deus em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 5, 'Examinai-vos a vós mesmos, se estais na fé; provai-vos a vós mesmos. Ou não conheceis a vós mesmos, que Jesus Cristo está em vós? A menos que vós estejais reprovados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 6, 'Mas espero que vós entendereis que nós não somos reprovados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 7, 'E eu desejo [pedindo] a Deus que nenhum mal façais; não para que sejamos achados aprovados, mas para que vós façais o bem, e nós sejamos como reprovados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 8, 'Porque nada podemos fazer contra a verdade, mas sim pela verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 9, 'Pois nós nos alegramos quando estamos fracos, e vós estais fortes; e isto também desejamos: o vosso aperfeiçoamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 10, 'Por isso eu escrevo estas coisas ausente; para que, quando estiver presente não use de rigor, segundo o poder que o Senhor tem me dado, para edificação, e não para destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 11, 'Quanto às demais coisas, irmãos, alegrai-vos, sede íntegros, consolai-vos, tenhais um mesmo entendimento, vivei em paz; e o Deus de amor e paz será convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 12, 'Saudai-vos uns aos outros com beijo santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 13, 'Todos os santos vos saúdam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 13, 14, 'A graça do Senhor Jesus Cristo, e o amor de Deus, e a comunhão do Espírito Santo seja com todos vós. Amém.[A Segunda Carta aos Coríntios foi escrita de Filipos, na Macedônia, e enviada por Tito e Lucas.]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 1, 'Paulo, apóstolo (não da parte dos seres humanos, nem por meio de homem algum, mas sim por Jesus Cristo, e por Deus Pai, que o ressuscitou dos mortos),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 2, 'e todos os irmãos que estão comigo, para as igrejas da Galácia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 3, 'Graça seja convosco, e também a paz de Deus Pai, e do nosso Senhor Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 4, 'que deu a si mesmo pelos nossos pecados, para nos tirar da presente era maligna, conforme a vontade do nosso Deus e Pai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 5, 'ao qual seja a glória para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 6, 'Admiro-me de que tão rapidamente desviastes daquele que vos chamou na graça de Cristo, em troca de outro evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 7, 'Não que haja outro [evangelho] ,porém há alguns que vos inquietam, e querem perverter o Evangelho de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 8, 'Porém, ainda que nós mesmos, ou um anjo do céu vos anuncie outro evangelho além do que já vos anunciamos, maldito seja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 9, 'Como já havíamos dito, volto também agora a dizer: se alguém vos anunciar outro evangelho além do que já recebestes, maldito seja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 10, 'Pois agora estou buscando a aprovação das pessoas, ou a de Deus? Ou procuro agradar a pessoas? Pois, se ainda tentasse agradar a pessoas, eu não seria servo de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 11, 'Mas faço-vos saber, irmãos, que o Evangelho anunciado por mim não se baseia em pessoas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 12, 'pois não o recebi, nem aprendi de ser humano algum, mas sim pela revelação de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 13, 'Pois já ouvistes da minha conduta no judaísmo, como em excesso eu perseguia e tentava destruir a Igreja de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 14, 'e [como] no judaísmo eu era mais avançado que muitos de minha idade em minha nação, e era extremamente zeloso das tradições de meus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 15, 'Mas quando Deus ( que me separou desde o ventre da minha mãe, e por sua graça me chamou ) se agradou'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 16, 'de revelar o seu Filho em mim, para eu evangelizar os gentios, de imediato, não fui pedir conselho com pessoa alguma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 17, 'nem subi a Jerusalém para os que já eram apóstolos antes de mim; em vez disso, parti para a Arábia, e voltei outra vez a Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 18, 'Então, depois de três anos, subi a Jerusalém para visitar Pedro, e estive com ele por quinze dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 19, 'E vi nenhum outro dos apóstolos, a não ser Tiago, o irmão do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 20, 'Ora, das coisas que vos escrevo, eis que, diante de Deus, não estou mentindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 21, 'Depois fui para as regiões da Síria e da Cilícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 22, 'Eu, porém, não era conhecido de rosto pelas igrejas da Judeia que estão em Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 23, 'mas somente haviam ouvido que “Aquele que antes nos perseguia agora anuncia a fé que antes tentava destruir”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 1, 24, 'E glorificavam a Deus por causa de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 1, 'Depois de passados catorze anos, subi outra vez a Jerusalém com Barnabé, levando comigo também Tito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 2, 'E, por causa de uma revelação, subi, e lhes declarei o Evangelho que prego entre os gentios. [Isso] , porém, foi em particular, com os mais influentes, para que eu eu não corresse ou tivesse corrido em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 3, 'Porém nem mesmo Tito, que estava comigo, sendo grego, foi obrigado a se circuncidar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 4, 'E [isso] por causa de falsos irmãos, que haviam se infiltrado, e entraram secretamente para espionar a nossa liberdade que temos em Cristo Jesus, a fim de nos tornar escravos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 5, 'A eles nem sequer por um momento cedemos a nos sujeitarmos, para que a verdade do Evangelho permanecesse em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 6, 'E quanto aos de maior influência (o que haviam sido antes não me importa; Deus não se interessa na aparência humana); esses, pois, que eram influentes, nada me acrescentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 7, 'Pelo contrário, quando viram que o Evangelho aos incircuncisos havia sido confiado a mim, assim como a Pedro, aos circuncisos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 8, '(pois aquele que operou em Pedro para o apostolado da circuncisão, esse operou também em mim para os gentios)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 9, 'e quando Tiago, Cefas, e João, que eram considerados como colunas, reconheceram a graça que me foi dada, eles estenderam as mãos direitas de comunhão a mim e a Barnabé, para que nós [fôssemos] aos gentios, e eles aos circuncisos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 10, 'sob a condição de que nos lembrássemos dos pobres; isso também procurei fazer com empenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 11, 'E quando Pedro veio a Antioquia, estive contra ele face a face, pois ele devia ser repreendido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 12, 'porque, antes que alguns que Tiago enviou chegassem, ele comia com os gentios; mas depois que chegaram, ele se retirou e se separou, temendo os que eram da circuncisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 13, 'E também com ele os outros judeus fingiram, de maneira que até Barnabé se deixou levar pela hipocrisia deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 14, 'Mas quando vi que não estavam agindo corretamente conforme a verdade do Evangelho, disse na presença de todos a Pedro: “Se tu, que és judeu, vives como gentio, e não como judeu, por que obrigas os gentios a viverem como judeus?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 15, 'Nós, que somos judeus por natureza, e não pecadores dentre os gentios,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 16, 'sabemos que o ser humano não é justificado pelas obras da Lei, mas sim pela fé em Jesus Cristo. Também nós temos crido em Cristo Jesus, para que fôssemos justificados pela fé em Cristo, e não pelas obras da Lei; pois ninguém se justificará pelas obras da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 17, 'Mas se nós, que buscamos ser justificados em Cristo, também nós mesmos somos achados pecadores, por isso Cristo contribui com o pecado? De maneira nenhuma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 18, 'Pois, se volto a construir as coisas que já destruí, provo que eu mesmo cometi transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 19, 'Pois pela Lei estou morto para a Lei, a fim de que eu viva para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 20, 'Já estou crucificado com Cristo. Estou vivendo não mais eu, mas Cristo vive em mim; e vivo a minha vida na carne por meio da fé no Filho de Deus, que me amou, e entregou a si mesmo por mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 2, 21, 'Não anulo a graça de Deus; pois, se a justiça é por meio da Lei, logo Cristo morreu por nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 1, 'Ó insensatos gálatas, quem vos iludiu para não obedecerdes à verdade? Diante dos vossos olhos Jesus Cristo foi retratado entre vós como crucificado!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 2, 'Só isto eu queria saber de vós: recebestes o Espírito pelas obras da Lei ou pela pregação da fé?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 3, 'Sois vós tão insensatos que, depois de começardes no Espírito, agora terminareis na carne?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 4, 'Experimentastes tantas coisas em vão? Se é que foi mesmo em vão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 5, 'Ora, aquele que vos dá o Espírito e que opera maravilhas entre vós [faz isso] por causa das obras da Lei ou da pregação da fé?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 6, 'Assim como “Abraão creu em Deus, e foi lhe reputado como justiça”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 7, 'entendei, pois, que os que são da fé são filhos de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 8, 'E a Escritura, prevendo que Deus justificaria os gentios pela fé, prenunciou o Evangelho a Abraão, [dizendo] : Todas nas nações serão abençoadas em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 9, 'Portanto, os que são da fé são abençoados com o crente Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 10, 'Pois todos os que são das obras da Lei estão sob maldição, porque está escrito: Maldito todo aquele que não permanecer em todas as coisas que estão escritas no livro da Lei, para fazê-las.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 11, 'E é evidente que pela Lei ninguém será justificado, porque: O justo viverá pela fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 12, 'A Lei não provém da fé; porém: Quem fizer estas coisas por elas viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 13, 'Cristo nos resgatou da maldição da Lei ao se fazer maldição para o nosso benefício (pois está escrito: Maldito todo aquele que for pendurado em um madeiro.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 14, 'com a finalidade de que a bênção de Abraão chegasse aos gentios em Cristo Jesus, para que recebêssemos a promessa do Espírito por meio da fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 15, 'Irmãos, estou falando em termos humanos: ainda que seja o pacto de uma pessoa, depois de confirmado, ninguém o anula, nem lhe acrescenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 16, 'Ora, as promessas foram ditas a Abraão e à sua descendência. E não diz: “E às descendências” como que [falando] de muitos, mas sim como a um: “E à tua descendência”, que é Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 17, 'Mas digo isto: o pacto foi confirmado anteriormente por Deus em Cristo; e a Lei que veio quatrocentos e trinta anos depois não o invalida de maneira que anule a promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 18, 'Pois, se a herança é pela Lei, já não é pela promessa; mas foi por meio da promessa que Deus a concedeu gratuitamente a Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 19, 'Para que, pois, é a Lei? Ela foi ordenada por causa das transgressões, até que chegasse o descendente a quem a promessa havia sido feita; e foi posta pelos anjos na mão de um mediador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 20, 'Ora, o mediador não é de um só, mas Deus é um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 21, 'Acaso, pois, a Lei é contra as promessas de Deus? De maneira nenhuma! Pois, se a Lei houvesse sido entregue para que pudesse dar vida, na verdade a justiça teria sido pela Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 22, 'Mas a Escritura prendeu tudo debaixo do pecado a fim de que a promessa fosse dada aos crentes por meio da fé em Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 23, 'Porém, antes que a fé viesse, estávamos vigiados sob a Lei, e presos, até que a fé fosse revelada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 24, 'Dessa maneira, a Lei foi nosso tutor em condução a Cristo, para que pela fé fossemos justificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 25, 'Mas depois que a fé chegou, já não estamos mais sob um tutor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 26, 'pois todos vós sois filhos de Deus por meio da fé em Cristo Jesus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 27, 'pois todos vós que fostes batizados em Cristo já vos revestistes de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 28, 'Assim, não há judeu nem grego; não há servo nem livre; não há macho nem fêmea. Pois todos vós sois um em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 3, 29, 'E, se vós sois de Cristo, então sois descendência de Abraão, e herdeiros conforme a promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 1, 'Digo, porém, que, enquanto o herdeiro é criança, em nada é diferente do servo, ainda que seja senhor de tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 2, 'Mas está sob tutores e administradores, até o tempo determinado pelo pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 3, 'Assim também nós, quando éramos crianças, estávamos escravizados debaixo dos princípios elementares do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 4, 'Mas quando o tempo se completou, Deus enviou o seu Filho, nascido de mulher, nascido sob a Lei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 5, 'para redimir os que estavam sob a Lei, a fim de que nós recebêssemos a adoção como filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 6, 'E, como sois filhos, Deus enviou aos vossos corações o Espírito do seu Filho, que clama: “Aba, Pai!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 7, 'Portanto, tu já não és mais servo, mas sim filho; e se és filho, também és herdeiro de Deus por meio de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 8, 'Quando, porém, não conhecíeis a Deus, vós servíeis aos que por natureza não são deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 9, 'Mas agora, que conheceis Deus, mais que isso, por Deus sois conhecidos, por que voltais outra vez aos fracos e miseráveis princípios elementares, aos quais quereis servir de novo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 10, 'Vós guardais dias, meses, tempos, e anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 11, 'Temo a vosso respeito de que talvez eu tenha trabalhado para convosco em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 12, 'Rogo-vos, irmãos, que sejais como eu, pois também eu sou como vós. Nenhum mal me fizestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 13, 'E vós sabeis que foi com uma enfermidade da carne que vos anunciei o Evangelho pela primeira vez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 14, 'E não cedestes à tentação de ter desprezo ou repugnância por meu aspecto físico; ao contrário, vós me recebestes como a um mensageiro de Deus, como ao [próprio] Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 15, 'O que houve, pois, com a vossa alegria? Pois eu vos dou testemunho de que, se fosse possível, teríeis arrancado os vossos próprios olhos para dá-los a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 16, 'Tornei-me, por acaso, vosso inimigo por ter vos dito a verdade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 17, 'Eles têm interesse por vós, mas não com boa intenção; mas querem vos isolar [de mim] ,para que vós mostreis interesse por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 18, 'É bom, porém, mostrar interesse para o bem sempre, e não somente quando estou presente convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 19, 'Meus filhinhos, por quem volto a sofrer dores de parto, até que Cristo seja formado em vós:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 20, 'queria eu estar agora presente convosco, e mudar meu tom de voz, pois estou perplexo a vosso respeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 21, 'Respondei-me vós, que quereis estar sob a Lei: não ouvis a Lei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 22, 'Pois está escrito que Abraão tinha dois filhos: um da escrava, e outro da livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 23, 'O da escrava nasceu segundo a carne, mas o da livre, pela promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 24, 'Isto serve de ilustração, pois estes são dois pactos: um é o do monte Sinai, que gera filhos para a escravidão, que é Agar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 25, 'Pois esta Agar é o monte Sinai, na Arábia, e corresponde à Jerusalém de agora, e é escravizada com os filhos dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 26, 'Mas a Jerusalém de cima é livre; esta é a mãe de todos nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 27, 'Pois está escrito: Alegra-te, ó estéril, que não geras filhos; extravasa gritando de júbilo, tu, que não estás de parto; porque muitos mais são os filhos da solitária, que os da que tem marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 28, 'Nós, porém, irmãos, como Isaque, somos filhos da promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 29, 'Porém, assim como naquele tempo o que nasceu segundo a carne perseguia o que [nasceu] segundo o Espírito, assim também é agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 30, 'Mas o que diz a Escritura? Expulsa a escrava e o filho dela, porque de maneira nenhuma o filho da escrava herdará com o filho da livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 4, 31, 'Portanto, irmãos, não somos filhos da escrava, mas sim da livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 1, 'Estai, pois, firmes na liberdade com que Cristo nos libertou, e não volteis a vos prender com o jugo da escravidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 2, 'Eis que eu, Paulo, vos digo, que se vos deixardes circuncidar, Cristo vos será útil em nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 3, 'E de novo atesto que todo homem que se deixar circuncidar está obrigado a obedecer a toda a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 4, 'Desligados estais de Cristo, vós que [quereis] ser justos pela Lei; da graça caístes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 5, 'Pois, por meio do Espírito, pela fé, aguardamos a esperança da justiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 6, 'porque, em Cristo Jesus, nem a circuncisão nem a incircuncisão tem valor algum; mas sim a fé, que opera por meio do amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 7, 'Estáveis correndo bem; quem vos impediu de obedecerdes à verdade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 8, 'Esta persuasão não parte daquele que vos chama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 9, 'Um pouco de fermento leveda toda a massa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 10, 'Acerca de vós, confio no Senhor de que não mudareis a vossa mentalidade; mas aquele que vos perturba, seja quem for, sofrerá o julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 11, 'Mas se eu, irmãos, ainda prego a circuncisão, por que, então, sou perseguido? Então a ofensa da cruz está anulada!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 12, 'Gostaria que aqueles que estão vos perturbando castrassem a si mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 13, 'Pois vós, irmãos, fostes chamados para a liberdade. Somente não [useis] a liberdade como oportunidade para a carne; em vez disso, servi-vos uns aos outros pelo amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 14, 'Pois toda a Lei se cumpre em uma só regra, que é: Amarás ao teu próximo como a ti mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 15, 'Se, porém, mordeis e devorais uns aos outros, cuidado para não vos destruirdes mutuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 16, 'Mas eu digo: andai no Espírito, e não executeis o mau desejo da carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 17, 'Pois a carne deseja contra o Espírito, e o Espírito contra a carne; e estes se opõem mutuamente, para que não façais o que quereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 18, 'Mas, se sois guiados pelo Espírito, não estais debaixo da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 19, 'As obras da carne são evidentes. São elas: adultério, pecado sexual, impureza, devassidão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 20, 'idolatria, feitiçaria, inimizades, brigas, ciúmes, iras, rivalidades egoístas, desavenças, facções,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 21, 'invejas, homicídios, bebedices, orgias, e coisas semelhantes a essas, das quais eu havia vos dito anteriormente; assim como eu também haviavos dito antes que os que praticam tais coisas não herdarão o Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 22, 'Mas o fruto do Espírito é: amor, alegria, paz, paciência, benignidade, bondade, fidelidade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 23, 'mansidão, domínio próprio. Contra essas coisas não há lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 24, 'Os que são de Cristo crucificaram a carne com as paixões e os maus desejos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 25, 'Se vivemos no Espírito, também no Espírito andemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 5, 26, 'Não nos tornemos presunçosos, irritando uns aos outros, e invejando uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 1, 'Irmãos, se alguém for surpreendido em algum pecado, vós que sois espirituais, restaurai ao tal com espírito de mansidão, prestando atenção a ti mesmo, para que não sejas tentado também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 2, 'Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 3, 'Pois, se alguém pensa ser alguma coisa, sendo nada, engana a si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 4, 'Cada um, porém, examine a sua própria obra, e então terá orgulho em si mesmo sozinho, e não em outro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 5, 'pois cada um levará a sua própria carga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 6, 'Mas aquele que é instruído na palavra compartilhe todas as boas coisas com aquele que o instrui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 7, 'Não vos enganeis: Deus não se deixa escarnecer; pois, o que o ser humano semear, isso também colherá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 8, 'Pois quem semear para a sua carne, da carne colherá degradação; mas quem semear para o Espírito, do Espírito colherá a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 9, 'Porém não cansemos de fazer o bem, pois no tempo devido colheremos, se não desistirmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 10, 'Portanto, enquanto temos oportunidade, façamos o bem a todos; mas principalmente aos familiares da fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 11, 'Olhai como são grandes as letras que vos escrevi da minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 12, 'Todos os que querem mostrar boa aparência na carne, estes vos obrigam a vos circuncidarem, somente para não serem perseguidos por causa da cruz de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 13, 'Pois nem mesmo os que se circuncidam guardam a Lei; mas querem que vos circuncideis, para se orgulharem de vossa carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 14, 'Mas longe de mim esteja me orgulhar, a não ser na cruz do nosso Senhor Jesus Cristo; por meio dela, o mundo está crucificado para mim, e eu para o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 15, 'Pois em Cristo Jesus, nem a circuncisão tem valor algum, nem a incircuncisão; mas sim a nova criatura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 16, 'E todos os que andarem conforme esta regra, paz e misericórdia estejam sobre eles, e sobre o Israel de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 17, 'De agora em diante, ninguém me perturbe, porque trago no meu corpo as marcas do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 48, 'Gálatas', 'Gl', 6, 18, 'A graça do nosso Senhor Jesus Cristo seja com o vosso espírito, irmãos. Amém![Escrita de Roma para os Gálatas]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 1, 'Paulo, apóstolo de Jesus Cristo pela vontade de Deus, aos santos que estão em Éfeso, e fiéis em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 2, 'Graça e paz, de Deus nosso Pai, e do Senhor Jesus Cristo, [sejam] convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 3, 'Bendito seja o Deus e Pai do nosso Senhor Jesus Cristo, que nos abençoou com todas as bênçãos espirituis nos lugares celestiais em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 4, 'Assim como nos escolheu nele antes da fundação do mundo, para que fôssemos santos e irrepreensíveis diante dele em amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 5, 'E nos predestinou como filhos adotados por meio de Jesus Cristo para si mesmo, conforme o bom prazer de sua vontade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 6, 'para louvor da glória de sua graça, pela qual nos fez aceitáveis no Amado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 7, 'Nele temos a libertação pelo seu sangue, o perdão dos pecados, conforme as riquezas da sua graça,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 8, 'que ele fez transbordar em nós em toda sabedoria e prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 9, 'E nos revelou o mistério da sua vontade, conforme o seu bom prazer, que propôs nele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 10, 'para a administração do cumprimento dos tempos, [isto é,] voltar a reunir todas as coisas em Cristo, tanto as que [estão] nos céus, quanto as que [estão] na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 11, 'Nele também fomos feitos herança, havendo sido predestinados conforme o propósito daquele que faz todas as coisas segundo o conselho da sua vontade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 12, 'para que fôssemos para louvor da sua glória, nós os que primeiro esperamos em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 13, 'E também vós, depois que ouvistes a palavra da verdade, o evangelho da vossa salvação, e nele crestes, nele fostes selados com o Espírito Santo da promessa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 14, 'que é a garantia da nossa herança, até a libertação da propriedade [de Deus] , para louvor da sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 15, 'Por isso eu, desde que ouvi da fé que há entre vós no Senhor Jesus, e do amor a todos os santos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 16, 'não paro de agradecer [a Deus] por vós, lembrando-me de vós em minhas orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 17, '[Oro] para que o Deus de nosso Senhor Jesus Cristo, o Pai glorioso , vos dê o Espírito de sabedoria e de revelação no conhecimento dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 18, 'e que sejam iluminados os olhos do vosso entendimento, para que conheçais qual é a esperança para a qual ele chamou, quais [são] as riquezas da gloriosa herança dele nos santos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 19, 'e qual é a superabundante grandeza do seu poder para nós, que cremos, conforme a operação da sua poderosa força,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 20, 'a qual ele operou em Cristo, ressuscitando-o dos mortos; e o colocou à direita dele nos céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 21, 'acima de todo governo, autoridade, poder, domínio, e de todo nome que se nomeia, não só nesta era, mas também na futura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 22, 'Ele também sujeitou todas as coisas debaixo dos seus pés, e o constituiu por cabeça sobre todas as coisas para a Igreja,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 1, 23, 'que é o seu corpo, a plenitude daquele que enche tudo em todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 1, 'E vós estáveis mortos em ofensas e pecados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 2, 'nos quais antes andastes conforme o proceder deste mundo, conforme o príncipe do poder do ar, do espírito que agora opera nos filhos da desobediência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 3, 'Entre esses também todos nós antes andávamos nos desejos da nossa carne, fazendo a vontade da carne e dos pensamentos; e éramos por natureza filhos da ira, como também os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 4, 'Mas Deus, que é rico em misericórdia, pelo seu muito amor com que nos amou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 5, 'estando nós ainda mortos em [nossas] ofensas, nos deu vida juntamente com Cristo (pela graça sois salvos),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 6, '[nos] ressuscitou, juntamente [com ele] , e [nos] fez sentar nos lugares celestiais, em Cristo Jesus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 7, 'para mostrar nos tempos futuros as abundantes riquezas da sua graça, pela [sua] bondade conosco em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 8, 'Porque pela graça sois salvos, por meio da fé; e isto não [vem] de vós; [é] dom de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 9, 'não por obras, para que ninguém tenha orgulho de si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 10, 'Pois nós fomos feitos por ele, criados em Cristo Jesus para as boas obras, que Deus preparou para que nelas andássemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 11, 'Portanto, lembrai-vos de que vós, antes, éreis gentios na carne, e chamados de não-circuncidados pelos que se chamam participantes da circuncisão na carne, feita por mãos humanas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 12, 'que naquele tempo estáveis sem Cristo, excluídos da comunidade de Israel, e estranhos aos pactos da promessa, não tendo esperança, e sem Deus no mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 13, 'Mas agora em Cristo Jesus, vós que antes estáveis longe, chegastes para perto pelo sangue de Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 14, 'pois ele é a nossa paz. Dos dois [povos] ele fez um, e derrubou do meio o muro da separação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 15, 'Na sua carne ele desfez a inimizade da Lei dos mandamentos [que consistia] em ordenanças, para criar em si mesmo os dois em um novo homem, fazendo a paz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 16, 'e pela cruz reconciliar com Deus a ambos num só corpo, matando nela a inimizade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 17, 'Ele veio, e proclamou o evangelho da paz a vós que [estáveis] longe, e aos que estavam perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 18, 'Pois por meio dele ambos temos acesso ao Pai por um [mesmo] Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 19, 'Portanto, já não sois estrangeiros, nem forasteiros, mas sim, concidadãos dos santos, e membros da família de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 20, 'edificados sobre o fundamento dos apóstolos e dos profetas, do qual Jesus Cristo é a pedra principal da esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 21, 'Nele o edifício todo, bem ajustado, cresce para [ser] um templo santo no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 2, 22, 'Nele também vós sois juntamente edificados para [serdes] morada de Deus em Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 1, 'Por isso eu, Paulo, [sou] prisioneiro de Cristo Jesus, para o benefício de vós, gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 2, 'Se é que já ouvistes da responsabilidade acerca da graça de Deus, que me foi dada para vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 3, 'que por revelação me foi dado a conhecer este mistério (conforme já [vos] escrevi um pouco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 4, 'quando o ledes, podeis entender o meu entendimento deste mistério de Cristo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 5, 'Esse mistério em outras gerações não foi dado a conhecer aos seres humanos , como agora foi revelado pelo Espírito aos seus santos apóstolos e profetas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 6, '[isto é, ] que os gentios são conjuntamente herdeiros, [membros] de um mesmo corpo, e participantes da sua promessa em Cristo por meio do evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 7, 'Eu fui feito servidor desse [evangelho] conforme o dom da graça de Deus, que me foi dada segundo a operação do seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 8, 'A mim, o menor de todos os santos, foi dada esta graça de anunciar entre os gentios, por meio do Evangelho, as inimagináveis riquezas de Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 9, 'E para esclarecer a todos qual é a comunhão do mistério que desde as eras passadas esteve oculto em Deus, que criou todas as coisas por meio de Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 10, 'para que a multiforme sabedoria de Deus seja agora manifestada pela igreja aos domínios e autoridades nos lugares celestes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 11, 'conforme o eterno propósito que ele cumpriu em Cristo Jesus, nosso Senhor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 12, 'no qual temos coragem e acesso confiante pela fé nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 13, 'Portanto, eu [vos] peço que não vos desanimeis em minhas aflições por vós. Elas são a vossa glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 14, 'Por causa disso me ponho de joelhos diante do Pai do nosso Senhor Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 15, 'do qual toda a família nos céus e na terra recebe nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 16, '[Oro] para que, conforme a sua riquíssima glória, ele vos conceda que sejais fortalecidos com poder pelo seu Espírito no interior de cada um,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 17, 'para que Cristo habite em vossos corações pela fé. [Oro] para que vós estejais enraizados e firmados no amor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 18, 'e assim possais compreender, com todos os santos, qual é a largura, comprimento, profundidade, e altura,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 19, 'e conhecer o amor de Cristo, que excede o entendimento, para que sejais cheios de toda a plenitude de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 20, 'E quanto àquele que é poderoso para fazer tudo muito mais abundantemente do que pedimos ou pensamos, segundo o poder que opera em nós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 3, 21, 'a ele seja a glória na Igreja, em Cristo Jesus, por todas as gerações para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 1, 'Portanto, eu, o prisioneiro no Senhor, rogo-vos que andeis como é digno do chamado com que fostes chamados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 2, 'com toda humildade e mansidão; com paciência, tolerando uns aos outros em amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 3, 'Procurai guardar a unidade do Espírito pelo vínculo da paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 4, 'Há um [só] corpo, e um [só] Espírito, como também fostes chamados em uma [só] esperança do vosso chamado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 5, 'Um [só] Senhor, uma [só] fé, um [só] batismo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 6, 'um [só] Deus, e Pai de todos, que é acima de todos, por meio de todos, e em todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 7, 'Mas a graça foi dada a cada um de nós conforme a medida do dom de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 8, 'Por isso diz: Quando ele subiu ao alto, levou cativo o cativeiro, e deu dons às pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 9, '(O que significa este “ele subiu”, senão que ele também antes tinha descido às partes mais baixas da terra?)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 10, 'Aquele que desceu é também o mesmo que subiu muito acima de todos os céus, para preencher todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 11, 'E ele mesmo deu uns como apóstolos, outros como profetas, outros como evangelistas, e outros como pastores e instrutores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 12, 'para o aperfeiçoamento dos santos, para a obra do serviço, para a edificação do corpo de Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 13, 'até que todos cheguemos à unidade da fé e do conhecimento do Filho de Deus, à maturidade, à medida da estatura da plenitude de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 14, 'O fim disso é que não mais sejamos crianças inconstantes, levadas de um lado para outro por todo vento de doutrina, pelo engano dos pessoas que, para enganar, usam de fraudes com astúcia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 15, 'Pelo contrário, sigamos a verdade em amor, e cresçamos em tudo naquele que é a cabeça: Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 16, 'É dele que todo o corpo, bem ajustado e unido por todos os ligamentos, conforme a operação de cada parte na medida devida, proporciona o crescimento do corpo, para a sua própria edificação em amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 17, 'Portanto digo isso, e dou testemunho no Senhor, que não andeis mais como os outros gentios andam, na futilidade das suas mentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 18, 'Esses têm o entendimento nas trevas, e estão separados da vida de Deus pela ignorância que há neles, pela dureza do seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 19, 'Como se tornaram insensíveis, eles se entregaram à sensualidade, para cometerem com avidez toda impureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 20, 'Mas não foi assim que vós aprendestes de Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 21, 'se é que o ouvistes, e fostes ensinados nele, como a verdade está em Jesus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 22, 'quanto ao comportamento passado, que deveis abandonar o velho ser humano, que se corrompe pelos maus desejos de engano;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 23, 'que [deveis] vos renovar no espírito da vossa mente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 24, 'e que [deveis] vos revestir do novo ser humano, que é criado conforme Deus na verdadeira justiça e santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 25, 'Portanto, abandonai a mentira, e falai a verdade cada um ao seu próximo; pois somos membros uns dos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 26, 'Quando irardes, não pequeis; o sol não se ponha sobre a vossa ira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 27, 'nem deis lugar ao diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 28, 'O que furtava, não furte mais; em vez disso, trabalhe, operando com as mãos o bem, para que tenha o que repartir com o que tiver necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 29, 'Não saia de vossa boca palavra imoral; mas sim a boa para a edificação conforme a necessidade; para que comunique graça aos que a ouvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 30, 'E não entristeçais o Espírito Santo de Deus, no qual fostes selados para o dia da libertação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 31, 'Toda amargura, raiva, ira, gritaria, e maledicência sejam tiradas do meio de vós, assim como toda malícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 4, 32, 'Em vez disso, sede benignos uns com os outros, misericordiosos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 1, 'Portanto, sede imitadores de Deus, como filhos amados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 2, 'e andai em amor, como também Cristo nos amou, e se entregou por nós como oferta e sacrifício de cheiro suave a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 3, 'Mas o pecado sexual, e toda impureza ou cobiça, nem mesmo se nomeie entre vós, como convém a santos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 4, 'nem imoralidades, nem palavras tolas, nem escárnios, que não convêm; em vez disso, atos de gratidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 5, 'Pois sabeis disto, que nenhum pecador no sexo, ou impuro, ou ganancioso, que é idólatra, tem herança no reino de Cristo e de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 6, 'Ninguém vos engane com palavras vazias; pois por essas coisas a ira de Deus vem sobre os filhos da desobediência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 7, 'Portanto não sejais parceiros deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 8, 'Pois antes vós éreis trevas, mas agora [sois] luz no Senhor; andai como filhos da luz'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 9, '(porque o fruto do Espírito[consiste] em toda bondade, justiça, e verdade),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 10, 'buscando descobrir o que agrada ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 11, 'E não participeis das obras infrutíferas das trevas, pelo contrário, reprovai-as.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 12, 'pois é vergonhoso até dizer o que eles fazem em segredo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 13, 'Mas todas essas coisas, quando são reprovadas, tornam-se visíveis pela luz, porque tudo o que se se torna visível é luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 14, 'Por isso se diz: Desperta tu, que dormes, e levanta-te dos mortos, e Cristo te iluminará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 15, 'Portanto vede cuidadosamente como vos conduzis, não como tolos, mas sim como sábios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 16, 'aproveitai o tempo, porque os dias são maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 17, 'Por isso, não sejais imprudentes, mas entendei qual é a vontade do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 18, 'E não fiqueis bêbados com vinho, em que há devassidão, mas enchei-vos do Espírito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 19, 'falando entre vós com salmos, hinos e cânticos espirituais; cantando e louvando ao Senhor no vosso coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 20, 'agradecendo sempre por tudo a Deus, o Pai, no nome do nosso Senhor Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 21, 'sujeitando-vos uns aos outros no temor a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 22, 'Mulheres, sujeitai-vos aos vossos próprios maridos, assim como ao Senhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 23, 'porque o marido é o cabeça da mulher, como também Cristo é o cabeça da Igreja, e ele é o salvador do corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 24, 'Mas, assim como a Igreja está sujeita a Cristo, assim também as mulheres [estejam] em tudo sujeitas aos seus próprios maridos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 25, 'Maridos, amai as vossas próprias esposas, assim como também Cristo amou a Igreja, e se entregou por ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 26, 'a fim de a santificar, havendo [a] purificado com a lavagem com água, pela palavra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 27, 'a fim de apresentar a si mesmo uma igreja gloriosa, sem mancha, nem ruga, nem algo semelhante; mas sim, santa e irrepreensível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 28, 'Assim os maridos devem amar as suas próprias esposas como os seus próprios corpos. Quem ama a sua esposa, ama a si mesmo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 29, 'pois ninguém jamais odiou a sua própria carne; mas a alimenta e sustenta, assim como também o Senhor à Igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 30, 'pois somos membros de seu corpo, da sua carne, e dos seus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 31, 'Por isso o homem deixará oseu pai e [a sua] mãe, e se ajuntará com a sua mulher; e os dois serão uma [só] carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 32, 'Esse é um grande mistério, mas estou dizendo quanto a Cristo e à Igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 5, 33, 'Assim também vós, cada um individualmente, ame a sua própria esposa como a si mesmo, e a mulher respeite o marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 1, 'Filhos, sede obedientes aos vossos pais no Senhor, porque isso é justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 2, 'Honra teu pai, e [tua] mãe (que é o primeiro mandamento com promessa);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 3, 'para que te vá bem, e vivas muito tempo sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 4, 'Pais, não provoqueis à ira os vossos filhos, mas criai-os na disciplina e correção do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 5, 'Servos, obedecei aos [vossos] senhores segundo a carne, com temor e tremor, em sinceridade do vosso coração, assim como a Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 6, 'não servindo somente quando vistos, como para agradar pessoas; mas sim, como servos de Cristo, fazendo de coração a vontade de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 7, 'servindo de boa vontade como ao Senhor, e não aos pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 8, 'Pois sabeis que cada um receberá do Senhor todo o bem que fizer, seja servo, seja livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 9, 'Senhores, fazei o mesmo a eles, abandonando as ameaças, pois sabeis também que o Senhor vosso e deles está nos céus, e [que] com ele não há acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 10, 'Por fim, meus irmãos, fortalecei-vos no Senhor e na força do seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 11, 'Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as ciladas do diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 12, 'Pois temos de lutar não contra carne e sangue, mas sim contra os domínios e poderes, contra os senhores das trevas deste mundo, contra os males espirituais nos lugares celestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 13, 'Portanto pegai toda a armadura de Deus, para que possais resistir no dia mal, e depois que fizerdes tudo, continuar firmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 14, 'Estai, pois, firmes, com a vossa cintura envolvida com o cinturão da verdade, e vestidos com a couraça da justiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 15, 'e calçados os pés com a prontidão do evangelho da paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 16, 'Sobretudo pegai o escudo da fé, com o qual podereis apagar todas as flechas inflamadas do maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 17, 'Pegai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 18, 'orando em todo tempo com toda oração e súplica no Espírito, e vigiando nisso com toda perseverança e súplica por todos os santos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 19, 'e por mim; a fim de que, quando eu abrir a boca, me seja dada palavra com ousadia, para tornar conhecido o mistério do evangelho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 20, 'pelo qual sou embaixador acorrentado; para que dele eu possa falar com ousadia, como devo falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 21, 'Para que também vós possais saber o que acontece comigo, [e] o que eu faço, Tíquico, o irmão amado, e fiel servidor do Senhor vos informará de tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 22, 'Eu o enviei até vós para isso, para que saibais o que acontece conosco, e ele conforte os vossos corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 23, 'Paz [seja] com os irmãos, e amor com fé, da parte de Deus Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 49, 'Efésios', 'Ef', 6, 24, 'A graça [seja] com todos os que amam ao nosso Senhor Jesus Cristo com amor que não falha. Amém![Escrita de Roma para os efésios, e enviada por Tíquico]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 1, 'Paulo e Timóteo, servos de Jesus Cristo, a todos os santos em Cristo Jesus, que estão em Filipos, com os supervisores e servidores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 2, 'Haja convosco a graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 3, 'Agradeço ao meu Deus todas as vezes que me lembro de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 4, 'sempre em todas as minhas orações, com alegria, fazendo oração por todos vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 5, 'por causa da vossa cooperação com o Evangelho desde o primeiro dia até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 6, 'E disto tenho certeza: aquele que começou a boa obra em vós irá completá-la até o dia de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 7, 'Para mim é justo eu sentir isso de todos vós, pois vos tenho no coração, porque todos vós sois participantes comigo da graça, tanto nas minhas prisões, como na defesa e confirmação do Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 8, 'Pois Deus é minha testemunha de como sinto saudades de todos vós, com o afeto de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 9, 'E isto oro: que o vosso amor seja mais e mais abundante em conhecimento e em toda percepção,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 10, 'para que aproveis as melhores coisas, a fim de que sejais sinceros, sem ofensa, até o dia de Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 11, 'cheios dos frutos da justiça, que, por meio de Jesus Cristo, são para glória e louvor a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 12, 'Mas quero, irmãos, que saibais que as coisas me aconteceram foram para o avanço do Evangelho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 13, 'de maneira que se tornou evidente a toda a guarda pretoriana, e a todos os demais, que as minhas prisões são em Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 14, 'e que a maioria dos irmãos no Senhor, depois de ganharem confiança com as minhas prisões, ousam falar a Palavra muito mais, sem medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 15, 'É verdade que também alguns pregam a Cristo por inveja e rivalidade, porém outros, também, de boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 16, 'Uns em verdade anunciam a Cristo por rivalidade egoísta, não sinceramente, supondo que irão acrescentar aflição às minhas prisões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 17, 'Mas outros [anunciam] por amor, sabendo que fui posto para a defesa do Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 18, 'Que, pois? Afinal de qualquer maneira, ou com fingimento, ou em verdade, Cristo é anunciado; e nisto me alegro, e continuarei a me alegrar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 19, 'pois sei que isso me resultará em livramento pela vossa oração e pelo socorro do Espírito de Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 20, 'conforme a minha intensa expectativa e esperança, de que em nada me envergonharei. Ao contrário, com toda a confiança, como sempre, assim também agora Cristo será engrandecido no meu corpo, seja pela vida, seja pela morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 21, 'Pois, para mim, o viver é Cristo, e o morrer é lucro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 22, 'Mas, se este viver na carne for o fruto do meu trabalho, então não sei o que prefiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 23, 'pois estou pressionado por ambos [os lados] : tenho desejo de ser desligado, e estar com Cristo, o que é muito melhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 24, 'entretanto, ficar na carne é mais necessário por causa de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 25, 'E nisto confio e sei, que ficarei, e continuarei com todos vós, para que avanceis, e vos alegreis na fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 26, 'a fim de que a vossa alegria em Cristo Jesus seja abundante, por causa de mim, através da minha presença, de volta, convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 27, 'Tão somente procedei de maneira digna do Evangelho de Cristo, para que, seja quando eu venha e vos veja, seja ausente, ouça a vosso respeito de que estais num mesmo espírito, com um mesmo ânimo, combatendo juntos pela fé do Evangelho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 28, 'e que em nada vos amedronteis pelos adversários, o que para eles é, de fato, indício de perdição, mas para vós de salvação, e isso vem de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 29, 'Pois vos foi dado gratuitamente, quanto a Cristo, não somente o crer nele, mas também o sofrer por ele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 1, 30, 'de maneira que tendes o mesmo combate, que vistes em mim, e agora de mim ouvis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 1, 'Portanto, se há alguma consolação em Cristo, se há algum conforto de amor, se há alguma comunhão do Espírito, se há afetos e compaixões,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 2, 'completai a minha alegria: que penseis da mesma maneira, tenhais o mesmo amor, sejais unidos de ânimo, tendo um mesmo modo de pensar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 3, 'Nada [façais] por rivalidade egoísta ou por vanglória; ao contrário, por humildade cada um considere o outro superior a si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 4, 'Cada um não cuide [somente] do que é seu; mas cada um cuide também do que é dos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 5, 'Isto seja, para que esteja em vós este modo de pensar, que também esteve em Cristo Jesus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 6, 'mesmo ele sendo em forma de Deus, não considerou a igualdade a Deus como algo para se apegar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 7, 'Pelo contrário, ele esvaziou a si mesmo, tomando a forma de servo, e se tornou semelhante aos homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 8, 'e, quando se encontrava em forma humana, ele humilhou a si mesmo, sendo obediente até a morte, e morte de cruz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 9, 'Por isso Deus também o exaltou supremamente, e lhe deu um nome que é acima de todo nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 10, 'a fim de que no nome de Jesus se dobre todo joelho dos que estão nos céus, na terra, e debaixo da terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 11, 'e toda língua confesse que Jesus Cristo é o Senhor, para a glória de Deus Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 12, 'Portanto, meus amados, assim como sempre obedecestes, não somente na minha presença, mas muito mais agora na minha ausência, assim exercei a vossa salvação com temor e tremor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 13, 'pois é Deus quem opera em vós tanto o querer como o agir, conforme a [sua] boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 14, 'Fazei tudo sem murmurações nem brigas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 15, 'para que sejais irrepreensíveis e puros, filhos de Deus, inculpáveis no meio de uma geração corrupta e perversa, na qual brilhais como luminárias no mundo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 16, 'e mantende a palavra da vida, para que no dia de Cristo eu possa me orgulhar de que não tenho corrido nem trabalhado em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 17, 'E ainda que eu seja derramado como oferta sobre o sacrifício e serviço da vossa fé, alegro-me e contento-me com todos vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 18, 'e, pelo mesmo motivo, alegrai-vos e contentai-vos comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 19, 'Tenho esperança no Senhor Jesus de em breve vos enviar Timóteo, para que também eu me anime quando souber notícias de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 20, 'Pois não tenho ninguém de mesmo ânimo que se importe sinceramente convosco,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 21, 'pois todos buscam as suas próprias coisas, e não as de Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 22, 'Mas vós sabeis a prova que ele passou, porque serviu comigo no Evangelho como um filho ao pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 23, 'Assim, pois, espero enviá-lo, tão logo eu veja o que há de haver comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 24, 'Mas confio no Senhor de que também eu mesmo virei em breve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 25, 'Julguei necessário, porém, enviar-vos Epafrodito, meu irmão, cooperador, e companheiro de batalha, mensageiro enviado por vós, e auxiliador naquilo que necessito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 26, 'porque ele tinha muitas saudades de todos vós, e estava muito angustiado por haverdes ouvido de que ele havia ficado doente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 27, 'E ele ficou mesmo doente, quase a morrer; mas o Deus dele teve misericórdia, não somente dele, mas também de mim, para que eu não tivesse tristeza após tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 28, 'Por isso eu o enviei mais depressa, a fim de que, vendo-o de novo, alegrei-vos e eu fique menos triste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 29, 'Recebei-o, pois, no Senhor, com toda alegria; e honrai ao que são como ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 2, 30, 'pois, por causa da obra de Cristo, ele chegou perto da morte, arriscando a sua própria vida para suprir em meu benefício a falta do vosso serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 1, 'No restante, meus irmãos, alegrai-vos no Senhor. Não me é incômodo escrever as mesmas coisas, e [isso é] para a vossa segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 2, 'Cuidado com os cães! Cuidado com os que operam o mal! Cuidado com a mutilação!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 3, 'Pois a circuncisão somos nós, que servimos a Deus [pelo] Espírito, orgulhamo-nos em Cristo Jesus, e não confiamos na carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 4, 'Embora eu também tenho como confiar na carne. Se outro alguém pensa que pode confiar na carne, ainda mais eu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 5, 'circuncidado ao oitavo dia, da descendência de Israel, da tribo de Benjamim, hebreu de hebreus; segundo a lei, fariseu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 6, 'segundo o zelo, perseguidor da Igreja; segundo a justiça que há na lei, irrepreensível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 7, 'Mas o que para mim era ganho considerei como perda, por causa de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 8, 'E, na verdade, considero também todas as coisas como perda, por causa da superioridade de conhecer a Cristo Jesus, meu Senhor. Por ele aceitei perder todas [essas] coisas, e as considero como dejetos, a fim de que eu possa ganhar a Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 9, 'e que eu seja achado nele, não tendo a minha justiça proveniente da Lei, mas sim a que é pela fé em Cristo, a justiça da parte de Deus pela fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 10, 'para eu conhecer a ele, assim como o poder de sua ressurreição e a comunhão em seus sofrimentos, tornando-me conforme a ele em sua morte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 11, 'para que, de alguma maneira, eu alcance a ressurreição dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 12, 'Não que eu já [a] tenha obtido, ou que já seja perfeito; mas sigo a fim de alcançar aquilo para o qual eu também fui alcançado por Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 13, 'Irmãos, não considero como se já a tivesse obtido; mas uma coisa [faço] : esqueço as coisas que ficam para trás, e avanço para as que estão adiante,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 14, 'e prossigo para o alvo, ao prêmio do chamado de cima, de Deus em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 15, 'Por isso, todos nós que somos maduros, tenhamos essa [mesma] mentalidade; e se em algo pensais de maneira diferente, Deus também vos revelará isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 16, 'Porém, naquilo a que já chegamos, andemos conforme a mesma regra, e tenhamos a mesma mentalidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 17, 'Sede meus imitadores, irmãos, e observai atentamente os que assim andam, como o exemplo que tendes em nós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 18, 'pois, como muitas vezes eu vos disse, e agora também digo chorando, muitos andam como inimigos da cruz de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 19, 'O fim deles é a perdição. O Deus deles é o ventre, e têm orgulho do que deviam se envergonhar. Eles se importam mais com as coisas terrenas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 20, 'Mas nós somos cidadãos dos céus, de onde também esperamos um Salvador, o Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 3, 21, 'Ele transformará o nosso degradante corpo, para que seja conforme o seu corpo glorioso, segundo a operação do seu poder de sujeitar para si todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 1, 'Portanto, meus amados e queridos irmãos, minha alegria e coroa, permanecei assim, firmes no Senhor, amados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 2, 'Rogo a Evódia e rogo a Síntique que tenham uma mesma mentalidade no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 3, 'Peço também de ti, verdadeiro companheiro, que ajude a essas que lutaram no Evangelho comigo, como também com Clemente, e com os demais cooperadores, cujos nomes estão no livro da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 4, 'Alegrai-vos sempre no Senhor. Volto a dizer: alegrai-vos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 5, 'A vossa bondade seja conhecida por todas as pessoas. Perto está o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 6, 'Não estejais ansiosos por coisa alguma; mas em tudo, por meio de orações e súplicas com ações de gratidão, sejam os vossos pedidos conhecidos por Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 7, 'e a paz de Deus, que excede todo entendimento, guardará os vossos corações e as vossas mentes em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 8, 'No restante, meus irmãos, tudo o que é verdadeiro, tudo o que é respeitável, tudo o que é justo, tudo o que é puro, tudo o que é amável, tudo o que é de boa fama, se há alguma virtude, e se há algo digno de elogio, nisto pensai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 9, 'O que também aprendestes, recebestes, ouvistes, e vistes em mim, isso fazei; e o Deus da paz será convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 10, 'Alegrei-me muito no Senhor de que finalmente voltastes a vos lembrardes de mim; aliás, já estáveis lembrando, porém não tínheis oportunidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 11, 'Não digo isso por causa de alguma necessidade, pois já aprendi a contentar-me com o que tenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 12, 'Sei estar humilhado, e sei ter em abundância; em toda maneira e em todas as coisas estou instruído, tanto a estar farto, como a ter fome; tanto a ter em abundância, como a sofrer necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 13, 'Posso todas as coisas em Cristo que me fortalece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 14, 'Todavia, fizestes bem em compartilhardes da minha aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 15, 'E também vós, filipenses, sabeis que, no princípio do evangelho, quando parti da Macedônia, nenhuma igreja compartilhou comigo no dar e no receber, a não ser vós somente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 16, 'pois até em Tessalônica por uma e duas vezes me enviastes o que eu necessitava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 17, 'Não que eu busque doações, mas busco o fruto que aumente o crédito de vossa conta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 18, 'Mas de tudo tenho recebido, e tenho em abundância; estou plenamente abastecido, depois que recebi de Epafrodito o que de vossa parte [me foi enviado] ,como cheiro suave, e sacrifício aceitável e agradável a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 19, 'E meu Deus suprirá todas a vossas necessidades segundo as suas riquezas em glória em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 20, 'Ao nosso Deus e Pai seja a glória para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 21, 'Saudai a todos os santos em Cristo Jesus. Os irmãos que estão comigo vos saúdam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 22, 'Todos os santos vos saúdam, mas principalmente os da casa de César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 50, 'Filipenses', 'Fp', 4, 23, 'A graça do nosso Senhor Jesus Cristo esteja com todos vós. Amém! [Para os filipenses. Escrita de Roma, enviada por Epafrodito]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 1, 'Paulo, apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Timóteo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 2, 'aos santos e fiéis irmãos em Cristo, que estão em Colossos. [Haja] em vós a graça e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 3, 'Agradecemos ao Deus e Pai do nosso Senhor Jesus Cristo, sempre orando por vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 4, 'pois ouvimos falar da vossa fé em Cristo Jesus, e do amor [que tendes] para com todos os santos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 5, 'por causa da esperança que está reservada para vós nos céus. Anteriormente ouvistes dessa esperança pala palavra da verdade do evangelho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 6, 'que já chegou a vós, como também em todo o mundo; e vai frutificando assim como entre vós, desde o dia em que ouvistes e conhecestes a graça de Deus em verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 7, 'Aprendestes o evangelho por Epafras, nosso amado cooperador, que é um fiel servidor de Cristo em vosso favor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 8, 'Ele também nos declarou o vosso amor no Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 9, 'Por isso também, desde o dia que [o] ouvimos, não paramos de orar por vós, e de pedir que sejais cheios do conhecimento da sua vontade, em toda sabedoria e entendimento espiritual;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 10, 'para que possais andar dignamente [diante] do Senhor, agradando-lhe em tudo, frutificando em toda boa obra, e crescendo no conhecimento de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 11, 'capacitados em todo fortalecimento, segundo o poder da sua glória, em toda perseverança e paciência com alegria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 12, 'agradecendo ao Pai, que nos capacitou a participar da herança dos santos na luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 13, 'Ele nos tirou do domínio das trevas, e nos transportou para o reino do seu amado Filho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 14, 'em quem temos a libertação pelo seu sangue: o perdão dos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 15, 'Ele é a imagem do Deus invisível, o primogênito de toda a criação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 16, 'porque nele foram criadas todas as coisas que há nos céus e na terra, visíveis e invisíveis, sejam tronos, sejam domínios, sejam governos, sejam autoridades; todas as coisas foram criadas por ele e para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 17, 'Ele existe antes de todas as coisas, e nele todas as coisas se mantêm.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 18, 'E ele é a cabeça do corpo, da Igreja; ele é o princípio [e] o primogênito dentre os mortos, para que tenha a primazia entre todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 19, 'Pois foi do agrado [do Pai] que toda a plenitude habitasse nele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 20, 'e, havendo por ele feito a paz pelo sangue da sua cruz, por meio dele reconciliasse consigo mesmo todas as coisas, tanto as que estão na terra, como as que estão nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 21, 'Vós éreis separados [dele] , e inimigos no entendimento, em más obras. Porém agora ele vos reconciliou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 22, 'no seu corpo de carne, pela morte, para vos apresentar diante dele santos, irrepreensíveis e inculpáveis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 23, 'se, de fato, permaneceis fundados e firmes na fé, e não vos afastais da esperança do evangelho que ouvistes, que é pregado a toda criatura que há abaixo do céu, e do qual eu, Paulo, fui feito servidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 24, 'Agora me alegro nos meus sofrimentos por vós, e cumpro na minha carne o restante das aflições de Cristo, em benefício do seu corpo, que é a Igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 25, 'Dela eu fui feito servidor segundo a responsabilidade da parte de Deus que me foi dada para o vosso benefício, a fim de cumprir a palavra de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 26, 'o mistério que estava oculto desde os princípios dos tempos e das gerações; mas agora foi manifesto aos seus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 27, 'A eles Deus quis fazer que conhecessem as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, a esperança da glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 28, 'Ele é quem anunciamos, advertindo a toda pessoa, e ensinando a toda pessoa, com toda sabedoria; a fim de que apresentemos toda pessoa [como] completa em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 1, 29, 'Para isso eu também trabalho, lutando conforme a eficácia dele, que age em mim com poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 1, 'Pois quero que saibais como é grande a luta que tenho para o benefício de vós, dos que [estão] em Laodiceia, e de tantos quantos não viram meu rosto fisicamente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 2, 'para que os seus corações sejam consolados, e estejam unidos em amor, e em todas as riquezas da pleno entendimento, para conhecimento do mistério de Deus, e do Pai, e de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 3, 'Nele estão ocultos todos os tesouros da sabedoria e do conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 4, 'Digo isso para que ninguém vos engane com palavras persuasivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 5, 'Pois ainda que esteja ausente em corpo, todavia em espírito estou convosco, alegrando-me, e vendo a vossa ordem e a firmeza de vossa fé em Cristo.')
